"""Custom CUDA top-k kernel (two-phase chunked bitonic selection).

Phase 1: one block per (row, 4096-wide chunk) sorts the chunk in shared
         memory with a bitonic network over order-preserving 64-bit keys
         (float bits mapped to monotonic uint32, index in low 32 bits) and
         emits the chunk's top-k candidates.
Phase 2: one block per row sorts the concatenated candidates (<= 2048 keys)
         and writes the final top-k values/indices.
k == 1 uses a fused single-kernel argmax (max reduction over keys).
"""
import os
import torch
import torch.nn as nn

os.environ.setdefault("TORCH_CUDA_ARCH_LIST", "12.0")

from torch.utils.cpp_extension import load_inline

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>

#define CHUNK 4096
#define P1_THREADS 512
#define P2_THREADS 256
#define AM_THREADS 256

__device__ __forceinline__ unsigned int f2ord(float f) {
    unsigned int b = __float_as_uint(f);
    return (b & 0x80000000u) ? ~b : (b | 0x80000000u);
}
__device__ __forceinline__ float ord2f(unsigned int o) {
    unsigned int b = (o & 0x80000000u) ? (o ^ 0x80000000u) : ~o;
    return __uint_as_float(b);
}

__global__ void topk_phase1(const float* __restrict__ x,
                            unsigned long long* __restrict__ scratch,
                            int n, int k) {
    __shared__ unsigned long long s[CHUNK];
    const int row = blockIdx.y;
    const long long start = (long long)blockIdx.x * CHUNK;
    const float* base = x + (long long)row * n;
    const int len = (int)min((long long)CHUNK, (long long)n - start);
    const int t = threadIdx.x;
    #pragma unroll
    for (int i = 0; i < CHUNK / P1_THREADS; i++) {
        int m = t + i * P1_THREADS;
        unsigned long long key = 0ULL;
        if (m < len) {
            int col = (int)start + m;
            key = ((unsigned long long)f2ord(__ldg(base + col)) << 32) | (unsigned int)col;
        }
        s[m] = key;
    }
    __syncthreads();
    // bitonic network, descending
    for (int size = 2; size <= CHUNK; size <<= 1) {
        for (int stride = size >> 1; stride > 0; stride >>= 1) {
            #pragma unroll
            for (int i = t; i < CHUNK; i += P1_THREADS) {
                int j = i ^ stride;
                if (j > i) {
                    unsigned long long a = s[i], b = s[j];
                    bool up = ((i & size) == 0);
                    if ((a < b) == up) { s[i] = b; s[j] = a; }
                }
            }
            __syncthreads();
        }
    }
    unsigned long long* out = scratch + ((long long)row * gridDim.x + blockIdx.x) * k;
    if (t < k) out[t] = s[t];
}

__global__ void topk_phase2(const unsigned long long* __restrict__ scratch,
                            float* __restrict__ vals,
                            long long* __restrict__ idxs,
                            int chunks, int k, int P) {
    extern __shared__ unsigned long long s2[];
    const int row = blockIdx.x;
    const int t = threadIdx.x;
    const int M = chunks * k;
    const unsigned long long* in = scratch + (long long)row * M;
    for (int i = t; i < P; i += P2_THREADS) s2[i] = (i < M) ? in[i] : 0ULL;
    __syncthreads();
    for (int size = 2; size <= P; size <<= 1) {
        for (int stride = size >> 1; stride > 0; stride >>= 1) {
            for (int i = t; i < P; i += P2_THREADS) {
                int j = i ^ stride;
                if (j > i) {
                    unsigned long long a = s2[i], b = s2[j];
                    bool up = ((i & size) == 0);
                    if ((a < b) == up) { s2[i] = b; s2[j] = a; }
                }
            }
            __syncthreads();
        }
    }
    if (t < k) {
        unsigned long long key = s2[t];
        vals[(long long)row * k + t] = ord2f((unsigned int)(key >> 32));
        idxs[(long long)row * k + t] = (long long)(unsigned int)(key & 0xffffffffu);
    }
}

__global__ void topk_argmax(const float* __restrict__ x,
                            float* __restrict__ vals,
                            long long* __restrict__ idxs,
                            int n) {
    __shared__ unsigned long long sm[AM_THREADS];
    const int row = blockIdx.x;
    const float* base = x + (long long)row * n;
    const int t = threadIdx.x;
    unsigned long long best = 0ULL;
    for (int col = t; col < n; col += AM_THREADS) {
        unsigned long long key = ((unsigned long long)f2ord(__ldg(base + col)) << 32) | (unsigned int)col;
        if (key > best) best = key;
    }
    sm[t] = best;
    __syncthreads();
    for (int s = AM_THREADS / 2; s > 0; s >>= 1) {
        if (t < s && sm[t + s] > sm[t]) sm[t] = sm[t + s];
        __syncthreads();
    }
    if (t == 0) {
        unsigned long long key = sm[0];
        vals[row] = ord2f((unsigned int)(key >> 32));
        idxs[row] = (long long)(unsigned int)(key & 0xffffffffu);
    }
}

void topk_forward(torch::Tensor x, torch::Tensor vals, torch::Tensor idxs,
                  torch::Tensor scratch, int64_t chunks, int64_t P) {
    const int B = x.size(0);
    const int n = x.size(1);
    const int k = vals.size(1);
    auto stream = at::cuda::getCurrentCUDAStream();
    const float* xp = x.data_ptr<float>();
    float* vp = vals.data_ptr<float>();
    long long* ip = reinterpret_cast<long long*>(idxs.data_ptr<int64_t>());
    if (k == 1) {
        topk_argmax<<<B, AM_THREADS, 0, stream>>>(xp, vp, ip, n);
        return;
    }
    unsigned long long* sp = reinterpret_cast<unsigned long long*>(scratch.data_ptr<uint8_t>());
    dim3 grid((unsigned)chunks, (unsigned)B);
    topk_phase1<<<grid, P1_THREADS, 0, stream>>>(xp, sp, n, k);
    topk_phase2<<<B, P2_THREADS, (size_t)P * 8, stream>>>(sp, vp, ip, (int)chunks, k, (int)P);
}
"""

_cpp_src = "void topk_forward(torch::Tensor x, torch::Tensor vals, torch::Tensor idxs, torch::Tensor scratch, int64_t chunks, int64_t P);"

_ext = load_inline(
    name="topk_bitonic_ext",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["topk_forward"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)

CHUNK = 4096


class Model(nn.Module):
    def __init__(self, batch: int, n: int, k: int):
        super().__init__()
        self.batch, self.n, self.k = batch, n, k
        self.register_buffer("_dummy", torch.zeros(1))
        self.chunks = (n + CHUNK - 1) // CHUNK
        M = self.chunks * k
        P = 2
        while P < M:
            P *= 2
        self.P = P
        self._bufs = None

    def __call__(self, x):  # bypass nn.Module hook machinery (hot path)
        bufs = self._bufs
        if bufs is None:
            device = x.device
            vals = torch.empty(self.batch, self.k, dtype=torch.float32, device=device)
            idxs = torch.empty(self.batch, self.k, dtype=torch.int64, device=device)
            scratch = torch.empty(self.batch * self.chunks * self.k * 8,
                                  dtype=torch.uint8, device=device)
            bufs = self._bufs = (vals, idxs, scratch)
        vals, idxs, scratch = bufs
        _ext.topk_forward(x, vals, idxs, scratch, self.chunks, self.P)
        return vals, idxs

    def forward(self, x):
        return self.__call__(x)


# Module-level shims rebuilt by check.py / benchmark.py per shape.
batch = 64
n = 8192
k = 8


def get_inputs():
    x = torch.randn(batch, n, dtype=torch.float32)
    return [x]


def get_init_inputs():
    return [batch, n, k]
